{"path": "bowling.py", "content": "class BowlingGame:
    FRAMES = 10
    PINS = 10

    def __init__(self):
        self.rolls = []
        self.frame = 0          # index of the current frame (0-9)
        self.frame_rolls = []   # rolls in the current frame

    def _game_over(self):
        if self.frame < self.FRAMES - 1:
            return False
        r = self.frame_rolls
        if len(r) < 2:
            return False
        if len(r) == 2:
            return r[0] + r[1] < self.PINS  # open tenth frame ends after two
        return True

    def roll(self, pins):
        if not isinstance(pins, int) or pins < 0:
            raise ValueError("Negative roll is invalid")
        if pins > self.PINS:
            raise ValueError("Pin count exceeds pins on the lane")
        if self.frame >= self.FRAMES or self._game_over():
            raise IndexError("Cannot roll after game is over")

        r = self.frame_rolls
        if self.frame < self.FRAMES - 1:
            if r and r[0] + pins > self.PINS:
                raise ValueError("Pin count exceeds pins on the lane")
            r.append(pins)
            if pins == self.PINS and len(r) == 1 or len(r) == 2:
                self.frame += 1
                self.frame_rolls = []
        else:
            if len(r) == 1 and r[0] < self.PINS and r[0] + pins > self.PINS:
                raise ValueError("Pin count exceeds pins on the lane")
            if (len(r) == 2 and r[0] == self.PINS and r[1] < self.PINS
                    and r[1] + pins > self.PINS):
                raise ValueError("Pin count exceeds pins on the lane")
            r.append(pins)
        self.rolls.append(pins)

    def score(self):
        if not self._game_over():
            raise IndexError("Score cannot be taken until the end of the game")
        total = 0
        i = 0
        rolls = self.rolls
        for _ in range(self.FRAMES):
            if rolls[i] == self.PINS:
                total += self.PINS + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == self.PINS:
                total += self.PINS + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total
